  "reference.title": "Parcelas de referencia",
  "reference.explain": "Parcelas que evalúa un evaluador de referencia (un coordinador o un revisor que usted elige) y que cada recolector también evalúa sin que se le diga. Las respuestas de cada recolector se comparan luego con la referencia: su exactitud. Estos controles quedan aparte de las cifras de acuerdo, las diferencias y la cola de revisión, para no contar nada dos veces.",
