  "settings.aiIntro": "En la pestaña Calidad, el asistente (el modelo Gemini de Google) puede revisar las cifras de calidad y proponer notas de orientación y parcelas para controlar de nuevo. Nunca cambia nada. Está desactivado hasta que un coordinador lo active.",
  "settings.aiSent": "Qué se envía: las respuestas a preguntas de opción y de número, las preguntas y los textos de ayuda de la encuesta, y sus notas de orientación, con los nombres de las personas reemplazados por 'Persona A', 'Persona B'. Las coordenadas, los comentarios y las demás respuestas de texto nunca se envían.",
