  "person.newLinkHelp": "Collect Earth solo descarga el archivo del proyecto al unirse. Con este enlace, en Collect Earth: Archivo → Join cloud project..., péguelo y luego «Log in» con su cuenta: recibe el archivo del proyecto tal como está ahora. El enlace no se gasta y su rol no cambia; funciona una semana, y cualquier otra persona que lo abriera se uniría como recolector.",
