  "answers.blankFilteredOne": "{n} parcela de los filtros no tiene respuesta.",
  "answers.explain": "Cómo responde cada persona a las preguntas, según las primeras evaluaciones de las parcelas (los controles de calidad no se cuentan). Una respuesta que alguien da mucho más a menudo o mucho menos a menudo que el resto del equipo aparece como algo que vale la pena mirar: sus parcelas pueden ser distintas, o puede entender la pregunta de otra manera. Nada se bloquea ni se cambia.",
  "answers.explainTeam": "Cómo responde el equipo a las preguntas, según las primeras evaluaciones de las parcelas (los controles de calidad no se cuentan). Como revisor, usted ve solo las cifras del equipo: las respuestas de cada persona son para los coordinadores.",
  "answers.tooFewPlots": "Este filtro tiene menos de 5 parcelas, o solo parcelas de una persona. Los revisores ven las respuestas del equipo solo en grupos de al menos 5 parcelas de al menos 2 personas (si no, las respuestas serían las de una persona). Elija un archivo de parcelas, un valor o un período más amplio, o quite los filtros.",
