  "answers.flagsTitle": "Vale la pena mirar",
  "answers.flagsExplain": "Alguien con al menos 20 parcelas que responden a una pregunta, que da una respuesta al menos 10 puntos más a menudo o menos a menudo que el resto del equipo, una diferencia mayor de la que suele dar el azar. Con muchas personas y preguntas, algunas siguen siendo azar, y las parcelas de zonas distintas pueden diferir: mire las parcelas antes de juzgar. Las fechas son el día en que cada parcela se guardó por última vez, en su zona horaria.",
