  "answers.nonNumericColumn": "No es un número",
  "quality.reviewerNote": "Como revisor, aquí trabaja la cola de revisión (sus decisiones quedan con su nombre) y ve las parcelas que vale la pena mirar, las respuestas del equipo, la salud de la encuesta y la exactitud frente a las parcelas de referencia; el resto de la pestaña Calidad es de los coordinadores.",
  "flags.title": "Parcelas que vale la pena mirar",
  "flags.explain": "Parcelas encontradas por cómo se recolectaron, sin ningún control de calidad: enviadas muy poco después de la parcela anterior de la persona, con todas las respuestas iguales a las de esa, con una respuesta obligatoria vacía, o guardadas de nuevo después de una decisión. Ninguna es un error seguro, y no se bloquea ni se cambia nada: abra la parcela y juzgue usted.",
  "flags.requiredNote": "Solo cuentan como obligatorias las preguntas que el formulario exige sean cuales sean las demás respuestas. Una pregunta obligatoria solo bajo una condición, o que solo se muestra bajo una, no se puede juzgar aquí, así que nunca se cuenta.",
  "flags.requiredNone": "El formulario no tiene ninguna pregunta obligatoria sean cuales sean las demás respuestas, así que aquí no se puede encontrar ninguna respuesta obligatoria vacía.",
