  "flags.problemsNote": "Las parcelas con más de una primera evaluación y las que no están en ningún archivo de parcelas vienen de \"Problemas en los datos\", más abajo. Se cuentan todas, pero solo se pueden mostrar las que están entre los 500 primeros problemas en los datos (por orden de parcela).",
  "flags.problemsNoteReviewer": "Las parcelas con más de una primera evaluación y las que no están en ningún archivo de parcelas vienen de los problemas en los datos de los coordinadores. Se cuentan todas, pero solo se pueden mostrar las que están entre los 500 primeros (por orden de parcela).",
