  "training.explain": "Formez les photo-interprètes sur des parcelles à part, séparées des données du projet : rien de ce qui y est fait ne compte dans l'avancement, l'export, les contrôles ni les chiffres de qualité. Lors d'une calibration, tout le monde interprète les mêmes parcelles et vous voyez où les réponses concordent ; les réponses retenues deviennent l'interprétation attendue. Les parcelles d'apprentissage ont une interprétation attendue : juste après avoir soumis une parcelle, chacun voit ses réponses à côté de celle-ci dans Mon travail, avec votre explication, et obtient un score.",
