  "file.uploading": "Téléversement… {pct} %",
  "file.uploaded": "Fichier du projet téléversé. Les personnes qui rejoignent le projet à partir de maintenant reçoivent cette version. Celles qui l'ont rejoint avant gardent l'ancienne : Collect Earth ne reçoit la nouvelle que par un lien d'invitation. Dans la page de chaque personne, sous Personnes, créez un lien pour le nouveau fichier du projet ; dans Collect Earth, elles choisissent Fichier → Join cloud project..., le collent et cliquent sur « Log in » avec leur compte.",
  "file.wrongType": "Ce n'est pas un fichier .cep. Choisissez le fichier .cep de votre enquête, fait dans Collect Earth.",
  "file.round.title": "Phase d'évaluation",
  "file.round.added": "Nous avons ajouté à l'enquête un 'round' caché pour que les contrôles de qualité se fassent à l'aveugle. Les collecteurs reçoivent cette version en rejoignant le projet. Vous pouvez toujours télécharger le fichier que vous avez téléversé. Les contrôles de qualité ne se font à l'aveugle que pour les collecteurs qui utilisent la prochaine version de Collect Earth après la 1.23.19 : les versions antérieures montrent le 'round' de la parcelle dans Earth Map, l'application Google Earth Engine et la carte des parcelles, si bien qu'un collecteur peut reconnaître un contrôle.",
  "file.round.downloadOriginal": "Télécharger le fichier que vous avez téléversé",
