  "file.round.which": "Quel code marque une réévaluation ?",
  "file.round.noneOption": "Aucun : ici, round veut dire autre chose (par exemple une année)",
  "file.round.whichHelp": "Les enregistrements avec ce code comptent comme des réévaluations (contrôles de qualité). Avec Aucun, un enregistrement compte comme un contrôle quand la personne avait la parcelle comme copie à comparer.",
  "file.round.saved": "Enregistré.",
  "file.round.noneLate": "Votre enquête n'a pas de 'round'. Des données avaient déjà été collectées quand ce fichier a été téléversé, donc le serveur a laissé l'enquête telle quelle. Le tableau de bord distingue quand même les évaluations principales des contrôles. Sans 'round', importer dans Collect Earth les deux évaluations d'une parcelle les fait apparaître comme des conflits, car elles ont la même clé.",
  "file.round.carryOn": "Vous pouvez ajouter une clé appelée 'round' dans le concepteur d'enquêtes de Collect, ou continuer sans : le tableau de bord distingue quand même les évaluations principales des contrôles. Sans 'round', importer dans Collect Earth les deux évaluations d'une parcelle les fait apparaître comme des conflits, car elles ont la même clé.",
  "file.round.checkFile": "Vérifiez que c'est bien le fichier .cep de votre enquête, fait dans Collect Earth, et téléversez-le à nouveau.",
  "file.round.refusal.notAZip": "Le serveur n'a pas ajouté 'round' car ce fichier n'est pas un fichier de projet qu'il peut ouvrir.",
  "file.round.refusal.tooLarge": "Le serveur n'a pas ajouté 'round' car ce fichier est trop volumineux une fois décompressé.",
