  "file.round.refusal.severalKeys": "Le serveur n'a pas ajouté 'round' car l'enquête a déjà plus d'une clé, et il ne modifie que les enquêtes dont la seule clé est l'id de la parcelle.",
  "file.round.refusal.roundNotKey": "Le serveur n'a pas ajouté 'round' car l'enquête a déjà une question appelée 'round' qui n'est pas une clé.",
  "file.round.refusal.balloonMissing": "Le serveur n'a pas ajouté 'round' car ce fichier n'a pas de formulaire de parcelle (balloon.html).",
  "file.round.refusal.balloonMarkerMissing": "Le serveur n'a pas ajouté 'round' car il manque au formulaire de parcelle (balloon.html) la ligne qui indique où vont les colonnes supplémentaires du fichier de parcelles.",
  "file.round.refusal.balloonIdsMissing": "Le serveur n'a pas ajouté 'round' car il manque au formulaire de parcelle (balloon.html) la liste des champs d'id (EXTRA_ID_ATTRIBUTES).",
  "file.round.refusal.templateMissing": "Le serveur n'a pas ajouté 'round' car ce fichier n'a pas de modèle de carte (kml_template.fmt).",
