  "file.round.refusal.unknown": "Le serveur n'a pas ajouté 'round' à cette enquête.",
  "file.note.added": "Votre commentaire arrive dans Collect Earth : quand vous renvoyez une parcelle pour la revoir, chaque personne à qui elle retourne lit votre commentaire en haut du formulaire de la parcelle, sans pouvoir le modifier. Le serveur l'a ajouté à l'enquête ; le bouton ci-dessous télécharge le fichier tel que vous l'avez téléversé.",
  "file.note.myWork": "Vos commentaires sur les parcelles renvoyées arrivent toujours aux personnes dans Mon travail.",
