  "file.note.refusal.noteNameTaken": "Votre commentaire n'apparaît pas dans Collect Earth avec ce fichier du projet : l'enquête a déjà une question appelée 'coordinator_note'.",
  "file.note.refusal.nestedPlotColumns": "Votre commentaire n'apparaît pas dans Collect Earth avec ce fichier du projet : l'enquête remplit depuis le fichier de parcelles une question à l'intérieur d'un groupe, et le serveur n'ajoute le commentaire que lorsque le fichier de parcelles remplit des questions de la parcelle elle-même.",
