  "checks.title": "Contrôles automatiques",
  "checks.explain": "Collect Earth Cloud peut choisir des parcelles envoyées pour qu'une deuxième personne les évalue de nouveau, à l'aveugle : personne ne sait quelles parcelles sont des contrôles. Chaque parcelle choisie va, en copie, à quelqu'un qui ne l'a pas évaluée et qui a le moins de contrôles à faire. Elle lui parvient la prochaine fois qu'il ouvre Paramètres → « Projet » dans Collect Earth, ou qu'il y clique sur « Actualiser les attributions », puis sur « Appliquer ».",
