  "activity.setting.sampling": "des contrôles automatiques",
  "reference.title": "Parcelles de référence",
  "reference.explain": "Des parcelles qu'un évaluateur de référence (un coordinateur ou un réviseur que vous choisissez) évalue, et que chaque collecteur évalue aussi sans qu'on le lui dise. Les réponses de chaque collecteur sont ensuite comparées à la référence : son exactitude. Ces contrôles sont tenus à part des chiffres d'accord, des différences et de la file de révision, pour que rien ne soit compté deux fois.",
  "reference.reviewerExplain": "À quel point les réponses de chaque collecteur correspondent aux évaluations de référence des parcelles de référence. Les coordinateurs choisissent les parcelles de référence.",
  "reference.blind": "On ne dit pas aux collecteurs quelles parcelles sont de référence : elles leur arrivent dans leur fichier de parcelles comme les autres, après « Actualiser les attributions » (Paramètres → « Projet ») et « Appliquer » dans Collect Earth. Cette exactitude n'est ni sur leur page Mon travail ni dans leur rapport. Des collecteurs qui comparent leurs fichiers de parcelles entre eux peuvent remarquer les parcelles qu'ils ont tous ; le choix au hasard préfère les parcelles dont le collecteur n'a pas encore téléchargé de parcelles.",
