  "settings.aiTitle": "Assistant IA",
  "settings.aiSwitch": "Utiliser l'assistant IA dans ce projet",
  "settings.aiIntro": "Dans l'onglet Qualité, l'assistant (le modèle Gemini de Google) peut analyser les chiffres de qualité et proposer des notes d'orientation et des parcelles à contrôler de nouveau. Il ne change jamais rien. Il reste désactivé tant qu'un coordinateur ne l'active pas.",
  "settings.aiSent": "Ce qui est envoyé : les réponses aux questions à choix et numériques, les questions et les textes d'aide de l'enquête, et vos notes d'orientation, les noms des personnes étant remplacés par « Personne A », « Personne B ». Les coordonnées, les commentaires et les autres réponses en texte ne sont jamais envoyés.",
  "settings.aiSentViews": "Sur la page d'analyse, « Demander d'autres vues à l'IA » n'envoie que la structure de l'enquête (ses questions, listes de codes et libellés) : jamais une parcelle, une réponse ni une personne.",
  "settings.aiWhere": "Traité par {provider} ({model}), dans la région {region}.",
  "settings.aiWhereGlobal": "Traité par {provider} ({model}). Sa région est « global » : Google peut le traiter dans n'importe laquelle de ses régions. Le propriétaire du serveur peut fixer une région (AI_VERTEX_REGION).",
  "settings.aiConfirmTitle": "Activer l'assistant IA ?",
  "settings.aiConfirmTerms": "Avant de l'activer, vérifiez qu'envoyer ces données à ce fournisseur est permis par les accords de ce projet (avec le propriétaire des données, et les règles du pays), et par les conditions du fournisseur, que le propriétaire du serveur a acceptées.",
