  "answers.blankFilteredOne": "{n} parcelle des filtres n'a pas de réponse.",
  "answers.explain": "Comment chaque personne répond aux questions, d'après les premières évaluations des parcelles (les contrôles de qualité ne sont pas comptés). Une réponse que quelqu'un donne bien plus ou bien moins souvent que le reste de l'équipe est signalée comme à regarder : ses parcelles peuvent être différentes, ou la question comprise autrement. Rien n'est bloqué ni modifié.",
  "answers.explainTeam": "Comment l'équipe répond aux questions, d'après les premières évaluations des parcelles (les contrôles de qualité ne sont pas comptés). En tant que réviseur, vous voyez seulement les chiffres de l'équipe : les réponses de chaque personne sont pour les coordinateurs.",
  "answers.tooFewPlots": "Ce filtre contient moins de 5 parcelles, ou les parcelles d'une seule personne. Les réviseurs ne voient les réponses de l'équipe que pour des groupes d'au moins 5 parcelles d'au moins 2 personnes (sinon, ce seraient les réponses d'une seule personne). Choisissez un fichier de parcelles, une valeur ou une période plus large, ou effacez les filtres.",
