  "answers.flagsTitle": "À regarder",
  "answers.flagsExplain": "Quelqu'un avec au moins 20 parcelles répondant à une question, qui donne une réponse au moins 10 points plus ou moins souvent que le reste de l'équipe, un écart plus grand que ce que le hasard donne d'habitude. Avec beaucoup de personnes et de questions, certains restent dus au hasard, et des parcelles de zones différentes peuvent différer : regardez les parcelles avant de juger. Les dates sont le jour où chaque parcelle a été enregistrée pour la dernière fois, dans votre fuseau horaire.",
