  "quality.reviewerNote": "En tant que réviseur, vous travaillez ici la file de révision (vos décisions sont gardées avec votre nom) et voyez les parcelles à regarder, les réponses de l'équipe, la santé de l'enquête et l'exactitude par rapport aux parcelles de référence ; le reste de l'onglet Qualité est réservé aux coordinateurs.",
  "flags.title": "Parcelles à regarder",
  "flags.explain": "Parcelles trouvées d'après la façon dont elles ont été collectées, sans aucun contrôle de qualité : envoyées très peu de temps après la parcelle précédente de la personne, avec toutes les réponses identiques à celle-ci, avec une réponse obligatoire laissée vide, ou enregistrées de nouveau après une décision. Aucune n'est une erreur à coup sûr, et rien n'est bloqué ni modifié : ouvrez la parcelle et jugez par vous-même.",
  "flags.requiredNote": "Seules comptent comme obligatoires les questions que le formulaire exige quelles que soient les autres réponses. Une question obligatoire seulement sous une condition, ou affichée seulement sous une condition, ne peut pas être jugée ici : elle n'est jamais comptée.",
