  "health.title": "Santé de l'enquête",
  "health.explain": "Comment chaque question fonctionne en pratique, pour la prochaine version de l'enquête : combien de fois elle est laissée vide, combien de fois on y répond par une option comme « autre » ou « inconnu », combien les contrôles concordent, et combien de fois une décision a retenu la réponse du contrôle. Les questions à reformuler viennent en premier, chacune avec ses raisons. Rien ici ne modifie les données ni l'enquête.",
  "health.count": "{plots} premières évaluations de parcelles ; {checked} parcelles avec un contrôle de qualité, dont {decided} tranchées en faveur du contrôle.",
  "health.noData": "Il n'y a pas encore de premières évaluations.",
