  "reference.title": "Parcelas de referência",
  "reference.explain": "Parcelas que um avaliador de referência (um coordenador ou um revisor que você escolhe) avalia, e que cada coletor também avalia sem ser avisado. As respostas de cada coletor são então comparadas com a referência: a sua exatidão. Esses controles ficam à parte dos números de concordância, das diferenças e da fila de revisão, para nada ser contado duas vezes.",
