  "settings.aiIntro": "Na aba Qualidade, o assistente (o modelo Gemini do Google) pode revisar os números de qualidade e sugerir notas de orientação e parcelas para controlar de novo. Ele nunca muda nada. Fica desativado até que um coordenador o ative.",
