  "quality.reviewerNote": "Como revisor, você trabalha aqui a fila de revisão (suas decisões ficam com o seu nome) e vê as parcelas que vale a pena ver, as respostas da equipe, a saúde da pesquisa e a exatidão em relação às parcelas de referência; o resto da aba Qualidade é dos coordenadores.",
  "flags.title": "Parcelas que vale a pena ver",
  "flags.explain": "Parcelas encontradas pela forma como foram coletadas, sem nenhum controle de qualidade: enviadas muito pouco depois da parcela anterior da pessoa, com todas as respostas iguais às dessa, com uma resposta obrigatória vazia, ou salvas de novo depois de uma decisão. Nenhuma é com certeza um erro, e nada é bloqueado nem alterado: abra a parcela e julgue você mesmo.",
  "flags.requiredNote": "Só contam como obrigatórias as perguntas que o formulário exige quaisquer que sejam as outras respostas. Uma pergunta obrigatória só sob uma condição, ou mostrada só sob uma, não pode ser julgada aqui, por isso nunca é contada.",
