  "health.title": "Saúde da pesquisa",
  "health.explain": "Como cada pergunta funciona na prática, para a próxima versão da pesquisa: quantas vezes fica vazia, quantas vezes é respondida com uma opção como “outro” ou “desconhecido”, quanto os controles concordam e quantas vezes uma decisão ficou com a resposta do controle. As perguntas que vale a pena reformular vêm primeiro, cada uma com os seus motivos. Nada aqui altera os dados nem a pesquisa.",
  "health.count": "{plots} primeiras avaliações de parcelas; {checked} parcelas com controle de qualidade, {decided} delas decididas a favor do controle.",
  "health.noData": "Ainda não há primeiras avaliações.",
