  "shareLinks.title": "Links de andamento para financiadores",
  "shareLinks.intro": "Um link de andamento abre uma página, sem login, que mostra o nome deste projeto, quantas parcelas estão feitas, o gráfico de andamento, a previsão e a concordância de qualidade em um só número. Quem tiver o link pode abri-la até que você o revogue. Uma cópia impressa ou salva da página pode levar o endereço do link, então compartilhe-a com o mesmo cuidado.",
