  "local.signedOut": "Este painel funciona no seu computador, ao lado do Collect Earth, e não tem senha: o Collect Earth o abre para você, já conectado. Abra-o de novo pelo Collect Earth.",
  "progress.noPlotsLocal": "Ainda não há parcelas. Quando o seu projeto e o arquivo de parcelas estiverem abertos no Collect Earth, o seu andamento aparecerá aqui.",
