  "data.explainLocal": "Baixe tudo o que você coletou até agora em um arquivo que abre no Excel ou em qualquer planilha: uma linha para cada parcela.",
  "data.emptyLocal": "Ainda não há dados. Quando você salvar parcelas no Collect Earth, elas aparecem aqui.",
  "answers.titleLocal": "Suas respostas",
  "answers.explainLocal": "Como você responde a cada pergunta, a partir das suas primeiras avaliações das parcelas: para uma escolha, a parte das suas parcelas que dá cada resposta; para um número, como os números se distribuem. Nada é bloqueado nem alterado.",
  "answers.yourPlots": "Suas parcelas",
  "flags.explainLocal": "Suas parcelas encontradas pela forma como foram coletadas: enviadas muito pouco depois da sua parcela anterior, com todas as respostas iguais às dessa, ou com uma resposta obrigatória vazia. Nenhuma é com certeza um erro, e nada é bloqueado nem alterado: abra a parcela e julgue você mesmo.",
