  "flags.problemsNoteLocal": "As parcelas com mais de uma primeira avaliação e as que não estão em nenhum arquivo de parcelas são todas contadas, mas só se podem mostrar as que estão entre as 500 primeiras (por ordem de parcela).",
  "health.explainLocal": "Como cada pergunta funciona na prática, para a próxima versão da pesquisa: quantas vezes você a deixa vazia e quantas vezes a responde com uma opção como “outro” ou “desconhecido”. As perguntas que vale a pena reformular vêm primeiro, cada uma com os seus motivos. Nada aqui altera os dados nem a pesquisa.",
