  "health.noteOrderLocal": "Ordem: cada número só é julgado com pelo menos {min} parcelas. Primeiro as perguntas respondidas com “outro” e semelhantes em {other} ou mais das parcelas, depois as que ficam vazias em {empty} ou mais. Depois as outras, na ordem da pesquisa.",
